edits.new:
def project(partition):
    try:
        result = _project(partition)
    except BaseException as exc:
        try:
            _close_parquet_source()
            _memory_note("worker_exception")
            _memory_write("failure", {"exception": type(exc).__name__, "message": str(exc)[:2000],
                "original_rss_guard_raised": str(exc) == "EA_DIAGNOSTIC_WORKER_RSS_LIMIT"})
        except BaseException as diagnostic_exc:
            print("EA_WORKER_MEMORY_EVIDENCE_FAILED", os.getpid(), type(diagnostic_exc).__name__,
                  str(diagnostic_exc)[:1000], file=sys.stderr, flush=True)
        raise
    finally:
        _close_parquet_source()
    counts = MEMORY["parquet_io_counts"]
    if counts["current_open_handles"] != 0 or counts["opens"] != counts["closes"]:
        raise RuntimeError("EA_PARQUET_HANDLE_LIFECYCLE_NOT_CLOSED")
    result["parquet_io_lifecycle"] = dict(counts)
    if len(json.dumps(result, allow_nan=False).encode()) > STATE["cfg"]["worker_report_cap_bytes"]:
        raise RuntimeError("EA_DIAGNOSTIC_SELECTED_REPORT_TOO_LARGE")
    return result

